// RSS (XML) → Parse & Extract
// RSS raw data is a big XML string in $input.first().json.data
const xml = $input.first().json.data;

// Use regex to extract each <item>...</item>
const items = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;

while ((match = itemRegex.exec(xml)) !== null) {
  const block = match[1];

  // Extract fields from each item
  const title = block.match(/<title>(.*?)<\/title>/)?.[1] || '';
  const link = block.match(/<link>(.*?)<\/link>/)?.[1] || '';
  const pubDate = block.match(/<pubDate>(.*?)<\/pubDate>/)?.[1] || '';
  const creator = block.match(/<!\[CDATA\[(.*?)\]\]>/)?.[1] || '';

  // Extract all categories
  const cats = [];
  const catRegex = /<category><!\[CDATA\[(.*?)\]\]><\/category>/g;
  let catMatch;
  while ((catMatch = catRegex.exec(block)) !== null) {
    cats.push(catMatch[1]);
  }

  items.push({
    title: title.replace(/<!\[CDATA\[|\]\]>/g, ''),
    link,
    pubDate,
    author: creator,
    categories: cats.join(', ')
  });
}

return items.map(item => ({ json: item }));

// JSON → Filter & Reshape
// The exchange rate API returns 200+ currencies
// We only want the ones relevant to Taiwan students

const raw = $input.first().json;

// Pick currencies we care about
const targets = [
  { key: 'USDTWD', name: '美元→台幣' },
  { key: 'USDJPY', name: '美元→日圓' },
  { key: 'USDEUR', name: '美元→歐元' },
  { key: 'USDKRW', name: '美元→韓元' },
  { key: 'USDCNY', name: '美元→人民幣' },
  { key: 'USDGBP', name: '美元→英鎊' },
  { key: 'USDTHB', name: '美元→泰銖' },
  { key: 'USDAUD', name: '美元→澳幣' },
];

const results = targets
  .filter(t => raw[t.key])
  .map(t => ({
    json: {
      currency_pair: t.key,
      display_name: t.name,
      exchange_rate: raw[t.key].Exrate,
      last_updated: raw[t.key].UTC
    }
  }));

return results;

// HTML → Extract article titles & links
// iThome homepage HTML is unstructured — we need regex to dig out data

const html = $input.first().json.data;

// iThome article pattern: <p class="title"><a href="/news/...">Title</a></p>
const articles = [];
const regex = /<p class="title">\s*<a href="(\/news\/\d+)">(.*?)<\/a>/g;
let match;

while ((match = regex.exec(html)) !== null) {
  articles.push({
    title: match[2].trim(),
    url: 'https://www.ithome.com.tw' + match[1]
  });
}

// Deduplicate by URL
const seen = new Set();
const unique = articles.filter(a => {
  if (seen.has(a.url)) return false;
  seen.add(a.url);
  return true;
});

return unique.map((item, i) => ({
  json: {
    rank: i + 1,
    title: item.title,
    url: item.url
  }
}));

